@extends('layouts.admin')@section('admin_title','Vendor Stock Requests')@section('admin_content')<section class="aw-panel"><p>Receive vendor-delivered goods through the existing Inward and FIFO batch system. No quantity is changed until approval.</p><div class="table-scroll"><table><thead><tr><th>Vendor / Product</th><th>Batch / Invoice</th><th>Quantity / Cost</th><th>Expiry</th><th>Reason</th><th>Status</th><th>Review</th></tr></thead><tbody>@forelse($rows as $row)<tr><td>{{ $row->vendor_name }}<small>{{ $row->product_name }}</small></td><td>{{ $row->batch_number }}<small>{{ $row->invoice_number }}</small></td><td>{{ $row->quantity }} · {{ $money($row->unit_cost) }}</td><td>{{ $row->expires_on?:'—' }}</td><td>{{ $row->reason }}</td><td>{{ $row->status }}</td><td>@if($row->status==='Pending'&&auth()->user()->canManage('inventory'))<form method="post" action="{{ route('admin.vendor-stock-requests.review',$row->id) }}" data-confirm="Review this receipt? Approval adds stock through Inward.">@csrf<label>Inspection notes<input name="review_notes" minlength="5" maxlength="1000" required></label><button name="action" value="approve">Receive goods</button><button name="action" value="reject">Reject</button></form>@else{{ $row->review_notes }}@endif</td></tr>@empty<tr><td colspan="7">No vendor stock requests.</td></tr>@endforelse</tbody></table></div>{{ $rows->links() }}</section><section class="aw-panel"><h3>Vendor platform announcement</h3><form method="post" action="{{ route('admin.vendor-stock-requests.announcement') }}">@csrf<label>Message<textarea name="message" minlength="5" maxlength="500" required></textarea></label><button class="primary">Notify active vendors</button></form></section>@endsection
